(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.HomeWishShareImage = factory();
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';
  // Inline the existing banner art so image export also works from a local file preview.
  const artData = 'data:image/webp;base64,';
  let artPromise;

  function loadArt() {
    if (!artPromise) artPromise = new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error('Wish art unavailable'));
      image.src = artData;
    });
    return artPromise;
  }

  function countdownCaption(days, beforeTet = days > 0) {
    return beforeTet && Number.isInteger(days) && days >= 0 ? 'Tết chỉ còn ' + days + ' ngày' : '';
  }

  async function render(message, days, beforeTet) {
    const art = await loadArt();
    if (document.fonts) {
      await Promise.race([
        Promise.all([document.fonts.load('700 48px "Dancing Script"'), document.fonts.load('900 23px Nunito')]).catch(() => {}),
        new Promise((resolve) => setTimeout(resolve, 1500))
      ]);
    }
    const canvas = document.createElement('canvas');
    canvas.width = 1280;
    canvas.height = 427;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('Canvas unavailable');
    ctx.drawImage(art, 0, 0, 1280, 427);
    ctx.fillStyle = 'rgba(255,249,232,.80)';
    ctx.beginPath();
    ctx.roundRect(282, 72, 635, 280, 28);
    ctx.fill();
    ctx.strokeStyle = 'rgba(218,167,92,.75)';
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.textAlign = 'center';
    ctx.fillStyle = '#a12635';
    ctx.font = '900 23px Nunito, sans-serif';
    ctx.fillText('LỜI CHÚC TẾT 2027', 600, 118);
    ctx.font = '700 48px "Dancing Script", cursive';
    const lines = [];
    let line = '';
    for (const word of message.split(' ')) {
      const next = line ? line + ' ' + word : word;
      if (ctx.measureText(next).width > 600 && line) {
        lines.push(line);
        line = word;
      } else line = next;
    }
    if (line) lines.push(line);
    const firstY = 222 - (lines.length - 1) * 28;
    ctx.fillStyle = '#8c1c29';
    ctx.shadowColor = 'rgba(255,255,255,.9)';
    ctx.shadowBlur = 4;
    lines.forEach((text, index) => ctx.fillText(text, 600, firstY + index * 56));
    ctx.shadowBlur = 0;
    const caption = countdownCaption(days, beforeTet);
    if (caption) {
      ctx.fillStyle = '#824f35';
      ctx.font = '800 22px Nunito, sans-serif';
      ctx.fillText(caption, 600, 325);
    }
    return new Promise((resolve, reject) => canvas.toBlob((blob) => blob ? resolve(blob) : reject(new Error('Image export unavailable')), 'image/png'));
  }

  return { render, countdownCaption };
});
